installer-gui-script.script:
function pm_volume_check() {
    if(!(my.target.mountpoint.substr(0, 6) == "/Volumes")) {
        return false;
    }
    return true;
}
function pm_install_check() {
    if(system.version.ProductVersion < '10.3') {
        my.result.title = 'Failure';
        my.result.message = 'This software requires macOS 10.3 or later.';
        my.result.type = 'Fatal';
        return false;
    }
    return true;
}
